import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";

function Collections() {
  const [categories, setCategories] = useState([]);
  const navigate = useNavigate();

  // 1. Fetch data when the page loads
  useEffect(() => {
    fetch("http://localhost:5000/api/categories")
      .then((response) => response.json())
      .then((data) => {
        setCategories(data); // Save the data to our state
      })
      .catch((error) => {
        console.log("Error fetching data: ", error);
      });
  }, []);

  // 2. Simple function to match the category name to the correct picture
  const getImageForCategory = (categoryName) => {
    if (categoryName === "Cars") return "/cars.png";
    if (categoryName === "Series") return "/movies.png";
    if (categoryName === "Quotes") return "/Quotes.png";
    if (categoryName === "Sports") return "/sport.png";
    if (categoryName === "Music") return "/music.png";
    if (categoryName === "Art & Culture") return "/Art & Culture.png";
    
    return "/placeholder.png"; // If no match is found
  };

  return (
    <div style={{ backgroundColor: "#f9f9f9", minHeight: "100vh" }}>
      
      {/* Top Header Area */}
      <div style={{ backgroundColor: "white", padding: "40px", borderBottom: "1px solid #dddddd" }}>
        <p style={{ color: "gray", fontSize: "12px", letterSpacing: "2px", textTransform: "uppercase" }}>
          Our Craft
        </p>
        <h2 style={{ fontFamily: "serif" }}>Curated Collections</h2>
        <p style={{ color: "gray", maxWidth: "500px" }}>
          Explore our meticulously crafted series, where each frame is a testament to timeless design.
        </p>
      </div>

      {/* Grid Area */}
      <div className="container" style={{ marginTop: "40px", marginBottom: "40px" }}>
        <div className="row g-4">
          
          {/* Loop through the categories and create a card for each one */}
          {categories.map((cat) => (
            <div className="col-md-4" key={cat._id}>
              <div style={{ border: "1px solid #dddddd", backgroundColor: "white", height: "100%" }}>
                
                {/* Image Box */}
                <div style={{ height: "250px", borderBottom: "1px solid #dddddd" }}>
                  <img 
                    src={getImageForCategory(cat.name)} 
                    alt={cat.name}
                    style={{ width: "100%", height: "100%", objectFit: "cover" }}
                  />
                </div>

                {/* Text & Button Box */}
                <div style={{ padding: "20px" }}>
                  <h4 style={{ fontFamily: "serif", textTransform: "capitalize" }}>{cat.name}</h4>
                  <p style={{ color: "gray", fontSize: "14px", height: "50px" }}>
                    {cat.description}
                  </p>
                  
                  <button 
                    onClick={() => navigate("/gallery?category=" + cat._id)}
                    style={{ 
                      width: "100%", 
                      padding: "10px", 
                      backgroundColor: "white", 
                      border: "1px solid black",
                      cursor: "pointer",
                      marginTop: "10px"
                    }}
                  >
                    EXPLORE COLLECTION
                  </button>
                </div>

              </div>
            </div>
          ))}

        </div>
      </div>
    </div>
  );
}

export default Collections;
